     */
    @available(macOS 10.15, iOS 13.0, tvOS 13.0, watchOS 6.0, *)
    open class func writeAppFile(id: String, writeAppFileRequest: WriteAppFileRequest) async throws {
        return try await writeAppFileWithRequestBuilder(id: id, writeAppFileRequest: writeAppFileRequest).execute().body
    }

    /**
     Write one file inside the app's project directory.
     - POST /v1/apps/{id}/file
     - Bearer Token:
       - type: http
       - name: bearerAuth
     - parameter id: (path)  
     - parameter writeAppFileRequest: (body)  
     - returns: RequestBuilder<Void> 
     */
    open class func writeAppFileWithRequestBuilder(id: String, writeAppFileRequest: WriteAppFileRequest) -> RequestBuilder<Void> {
        var localVariablePath = "/v1/apps/{id}/file"
        let idPreEscape = "\(APIHelper.mapValueToPathItem(id))"
        let idPostEscape = idPreEscape.addingPercentEncoding(withAllowedCharacters: .urlPathAllowed) ?? ""
        localVariablePath = localVariablePath.replacingOccurrences(of: "{id}", with: idPostEscape, options: .literal, range: nil)
        let localVariableURLString = SpatioAPI.basePath + localVariablePath
        let localVariableParameters = JSONEncodingHelper.encodingParameters(forEncodableObject: writeAppFileRequest)

        let localVariableUrlComponents = URLComponents(string: localVariableURLString)

        let localVariableNillableHeaders: [String: Any?] = [
            "Content-Type": "application/json",
        ]

        let localVariableHeaderParameters = APIHelper.rejectNilHeaders(localVariableNillableHeaders)

        let localVariableRequestBuilder: RequestBuilder<Void>.Type = SpatioAPI.requestBuilderFactory.getNonDecodableBuilder()

        return localVariableRequestBuilder.init(method: "POST", URLString: (localVariableUrlComponents?.string ?? localVariableURLString), parameters: localVariableParameters, headers: localVariableHeaderParameters, requiresAuthentication: true)
    }
